// @ts-nocheck
/* eslint-disable */
// CSSD Central Hub user interface, ported from the standalone HTML version.
//
// Differences from the standalone file:
// - Records are read from and written to SharePoint lists (see store.ts) instead of localStorage.
// - Attachments are uploaded to the "CSSD Attachments" library instead of being embedded as data URLs.
// - Inline on* handlers were replaced by data-act / data-change / data-submit attributes with one
//   delegated listener, because SharePoint's Content Security Policy does not allow inline script.
// - All styles are scoped under .cssd-hub, and printing uses an isolated frame.
import { HubStore, HubState } from './store';
import { hubCss, PRINT_CSS } from './styles';

export interface HubOptions {
  root: HTMLElement;
  store: HubStore;
  userName: string;
  logoUrl: string;
  heroUrl: string;
}

const MAX_MB = 10;
const STALE_MS = 60000;

export function startHub(opts: HubOptions): () => void {
  const { root, store, logoUrl } = opts;
  const me = opts.userName || '';

  root.classList.add('cssd-hub');
  root.setAttribute('dir', 'ltr');
  root.innerHTML = `<style>${hubCss(opts.heroUrl)}</style><header><div class="brand"><img class="brand-logo" src="${esc(logoUrl)}" alt="CSSD Central Hub — Wrapped instrument set"><div><strong>CSSD</strong><small>Central Sterile Services Department</small></div></div><nav id="nav"></nav><div class="tools"><small class="muted" id="syncstatus" role="status"></small><button type="button" data-act="refresh" title="Reload records from SharePoint" aria-label="Reload records from SharePoint">↻</button><div class="clock" id="clock"></div></div></header><main id="app"><div class="loading">Loading CSSD records from SharePoint…</div></main><footer>Records are stored in SharePoint lists on this site · Access follows SharePoint site and list permissions<br>Initiative and project requirements: Shrooq Almeshari · Changes require prior written consent under an approved agreement</footer><div class="toast" id="toast" role="status" hidden></div>`;

  // ---------- helpers ----------
  function esc(s) { return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
  const $ = s => root.querySelector(s);
  const $$ = s => [...root.querySelectorAll(s)];
  const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  const time = () => new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Riyadh', hour: '2-digit', minute: '2-digit' }).format(new Date());
  const uid = () => crypto.randomUUID();
  const attr = (kind, name, args) => ` data-${kind}="${name}"${args.length ? ` data-args="${esc(JSON.stringify(args))}"` : ''}`;
  const act = (name, ...args) => attr('act', name, args);
  const chg = (name, ...args) => attr('change', name, args);
  const sub = (name, ...args) => attr('submit', name, args);
  const btn = (text, action, primary = false, ...args) => `<button type="button" ${primary ? 'class="primary"' : ''}${act(action, ...args)}>${text}</button>`;
  const panel = (n, title, body) => `<section class="panel"><div class="pt"><span class="num">${n}</span>${title}</div><div class="pb">${body}</div></section>`;
  const field = (id, label, type = 'text', value = '') => `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type === 'number' ? 'min="0"' : ''}>`;
  const textarea = (id, label, value = '') => `<label for="${id}">${label}</label><textarea id="${id}">${esc(value)}</textarea>`;
  function detailField(id, label, value, type = 'text', extra = '') { return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}" ${type === 'number' ? 'min="0" step="any" inputmode="decimal"' : ''} ${extra}>`; }
  function select(id, label, options, value) { return `<label for="${id}">${label}</label><select id="${id}">${options.map(x => `<option value="${esc(x)}" ${x === value ? 'selected' : ''}>${esc(x)}</option>`).join('')}</select>`; }
  function title(en, subtitle) { return `<div class="hero sectionhero"><h1>${en}</h1><h2 dir="ltr">${subtitle}</h2></div>`; }
  function toast(t) { const e = $('#toast'); if (!e) return; e.textContent = t; e.hidden = false; clearTimeout(toast.timer); toast.timer = setTimeout(() => e.hidden = true, 5500); }
  function scrollTop() { root.scrollIntoView({ behavior: 'smooth', block: 'start' }); }

  // ---------- state and SharePoint sync ----------
  let state: HubState = { orders: [], issues: [], loaners: [], endorsements: [], parameters: [], ifuDocuments: [], emergencies: [], recalls: [], management: { tasks: [], devices: [] } };
  let loaded = false, loadedAt = 0, pendingSaves = 0, disposed = false;
  let page = 'welcome', month = '', day = '', shift = 'ALL', selected = null, extItems = [{ name: '', requested: 1 }], externalReceipt = null;

  function setSync(t) { const e = $('#syncstatus'); if (e) e.textContent = t; }
  async function reloadState() {
    try { state = await store.load(); loaded = true; loadedAt = Date.now(); }
    catch (e) { toast(e.message || 'Unable to read records from SharePoint'); }
  }
  async function save() {
    pendingSaves++; setSync('Saving…');
    try { await store.sync(state); if (pendingSaves === 1) setSync('All changes saved'); return true; }
    catch (e) { setSync('Not saved'); toast((e && e.message) || 'Could not save to SharePoint'); await reloadState(); render(); return false; }
    finally { pendingSaves--; }
  }
  // Called after every change. Saving runs in the background; on failure the records are reloaded.
  function persist() { void save(); return true; }

  async function readFile(f) {
    if (f.size > MAX_MB * 1024 * 1024) throw new Error(`The file exceeds ${MAX_MB} MB`);
    if (!['application/pdf', 'image/png', 'image/jpeg'].includes(f.type)) throw new Error('Select a PDF, JPG or PNG file');
    toast('Uploading ' + f.name + '…');
    return await store.uploadFile(f, uid());
  }

  function printHtml(html) {
    const frame = document.createElement('iframe');
    frame.setAttribute('aria-hidden', 'true');
    frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0';
    document.body.appendChild(frame);
    const doc = frame.contentDocument;
    doc.open();
    doc.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>CSSD Central Hub</title><style>${PRINT_CSS}</style></head><body><div class="printonly" style="display:block;padding:25px;color:black">${html}</div></body></html>`);
    doc.close();
    const images = [...doc.images].filter(i => !i.complete).map(i => new Promise(r => { i.onload = i.onerror = r; }));
    Promise.all(images).then(() => { frame.contentWindow.focus(); frame.contentWindow.print(); setTimeout(() => frame.remove(), 60000); });
  }
  function download(name, text, type) { const url = URL.createObjectURL(new Blob([text], { type })), a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1500); }

  // ---------- navigation ----------
  async function go(p) {
    page = p;
    if (Date.now() - loadedAt > STALE_MS && !pendingSaves) await reloadState();
    render(); scrollTop();
  }
  const modules = [['staff', '▤', 'CSSD Staff', 'Incoming orders and receiving'], ['issues', '⚑', 'Reports / Issues', 'Reports and issue follow-up'], ['incharge', '♙', 'In-Charge', 'Endorsement & Parameters'], ['loaner', '▣', 'Loaner Sets', 'Loaner sets'], ['management', '▥', 'Department Management', 'Department management and dashboard'], ['ifu', '▧', 'IFU Library', 'Instructions for use library'], ['emergency', '⚡', 'Emergency Cases', 'Emergency cases'], ['recall', '↺', 'Recall', 'Recall and OR follow-up']];
  function updateClock() { const c = $('#clock'); if (c) c.textContent = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Riyadh', dateStyle: 'medium', timeStyle: 'short' }).format(new Date()); }
  function render() {
    if (!loaded || disposed) return;
    updateClock();
    $('#nav').innerHTML = page === 'welcome' ? '' : ['external', 'orRecall'].includes(page) ? btn('← Back', 'go', false, 'welcome') : modules.map(([p, i, en]) => `<button type="button" class="${page === p ? 'active' : ''}"${act('go', p)}>${i} ${en}</button>`).join('') + btn('← Back', 'go', false, 'welcome');
    $('#app').innerHTML = ({ welcome, internal, external, staff, issues, incharge, loaner, management: managementPage, ifu: ifuLibraryPage, emergency: emergencyPage, recall: recallPage, orRecall: orRecallPage }[page] || welcome)();
  }
  function icon(kind) { return kind === 'building' ? '<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M8 56h48M12 56V24h14V8h22v48M26 56V8M48 30h8v26M33 56V44h8v12"/><path d="M18 30v4m0 6v4m14-28v4m9-4v4m-9 7v4m9-4v4m-9 7v4m9-4v4"/></svg>' : '<svg viewBox="0 0 64 64" aria-hidden="true"><circle cx="24" cy="22" r="9"/><circle cx="45" cy="24" r="8"/><path d="M7 53v-6c0-11 34-11 34 0v6zM43 53h15v-8c0-8-9-11-15-9"/></svg>'; }
  function welcome() { return `<section class="hero welcome"><h1>Welcome to CSSD Central Hub</h1><h2 dir="ltr">Digital services for the Central Sterile Services Department</h2><p class="muted">Please select a section to continue</p><div class="choices"><button type="button" class="choice"${act('go', 'external')}><span class="icon">${icon('building')}</span><span>External Department<small>Clinic and OR orders</small></span></button><button type="button" class="choice internal"${act('go', 'internal')}><span class="icon">${icon('people')}</span><span>CSSD Internal<small>Incoming orders and department services</small></span></button></div></section>`; }
  function internal() { return title('CSSD Internal', 'Select an internal service') + `<div class="modules">${modules.map(([p, i, en, ar]) => `<button type="button" class="module"${act('go', p)}><span class="icon">${i}</span>${en}<small>${ar}</small></button>`).join('')}</div>`; }

  // ---------- external orders ----------
  function external() { return title('External Order', 'Clinic and OR orders') + `<div class="actions recall-portal-link">${btn('↺ OR recall follow-up', 'go', false, 'orRecall')}</div>` + `<div class="four">` + panel(1, 'Department details', select('etype', 'Order type', ['Clinic', 'Operating Room'], 'Clinic') + field('dept', 'Clinic name / Department') + field('by', 'Submitted by', 'text', me) + field('edate', 'Date', 'date', today()) + select('eshift', 'Shift', ['AM', 'PM', 'Night'], 'AM')) + panel(2, 'Instruments and quantities', `<div class="tablewrap"><table><thead><tr><th>Instrument</th><th>Qty</th><th></th></tr></thead><tbody>${extItems.map((x, i) => `<tr><td><input aria-label="Instrument name" value="${esc(x.name)}"${chg('extName', i)}></td><td><input aria-label="Quantity" class="qty" type="number" min="1" value="${x.requested}"${chg('extQty', i)}></td><td><button type="button" aria-label="Remove instrument"${act('removeExt', i)}>×</button></td></tr>`).join('')}</tbody></table></div><div class="actions">${btn('+ Add instrument', 'addExt')}</div>`) + panel(3, 'Priority and comments', `<label><input type="checkbox" id="rush"> ⚡ Rush — Urgent request</label>` + textarea('comment', 'Order comments') + `<p class="muted" dir="ltr">After submission, the order appears in CSSD under the selected month, date and shift.</p>`) + panel(4, 'Submit and receipt', `<p dir="ltr">Review the instruments and quantities, then submit the order to CSSD.</p>${btn('Submit order to CSSD', 'submitExternal', true)}<div id="sentreceipt">${externalReceipt ? receipt(externalReceipt) : ''}</div>${externalReceipt ? `<div class="actions">${btn('Print receipt', 'printExternalReceipt')}${btn('Open order in CSSD', 'openIncoming', false, externalReceipt.id)}</div>` : ''}`) + `</div>`; }
  function extName(i, el) { if (extItems[i]) extItems[i].name = el.value; }
  function extQty(i, el) { if (extItems[i]) extItems[i].requested = Number(el.value); }
  function addExt() { captureExt(); extItems.push({ name: '', requested: 1 }); render(); restoreExt(); }
  function removeExt(i) { captureExt(); extItems.splice(i, 1); render(); restoreExt(); }
  let extDraft = {};
  function captureExt() { for (const id of ['etype', 'dept', 'by', 'edate', 'eshift', 'comment', 'rush']) { const e = $('#' + id); if (e) extDraft[id] = e.type === 'checkbox' ? e.checked : e.value; } }
  function restoreExt() { for (const [k, v] of Object.entries(extDraft)) { const e = $('#' + k); if (e) { if (e.type === 'checkbox') e.checked = v; else e.value = v; } } }
  let submitting = false;
  async function submitExternal() {
    if (submitting) return;
    captureExt();
    const items = extItems.map(x => ({ name: x.name.trim(), requested: Number(x.requested), actual: Number(x.requested), condition: 'Good' }));
    if (!extDraft.dept?.trim() || !extDraft.by?.trim() || !extDraft.edate || !items.length || items.some(x => !x.name || !Number.isInteger(x.requested) || x.requested < 1)) { toast('Enter the department, sender, date and at least one instrument with a valid quantity.'); return; }
    submitting = true;
    try {
      await reloadState(); // pick up orders other users submitted, so the order number is unique
      const prefix = extDraft.etype === 'Clinic' ? 'CL' : 'OR', base = prefix + '-' + extDraft.edate.replaceAll('-', '') + '-'; let n = 1;
      while (state.orders.some(o => o.id === base + String(n).padStart(3, '0'))) n++;
      const o = { id: base + String(n).padStart(3, '0'), dept: extDraft.dept.trim(), type: extDraft.etype, date: extDraft.edate, shift: extDraft.eshift, time: time(), by: extDraft.by.trim(), rush: extDraft.rush, comment: extDraft.comment, status: 'New', items, files: [], receiver: '', witness: '', notes: '' };
      state.orders.push(o);
      if (!(await save())) return;
      externalReceipt = o; render(); restoreExt(); toast('Order submitted to CSSD: ' + o.id);
    } finally { submitting = false; }
  }
  function openIncoming(id) { const o = state.orders.find(x => x.id === id); if (!o) return; selected = id; month = o.date.slice(0, 7); day = o.date; shift = 'ALL'; go('staff'); }
  function statusTag(s) { return `<span class="tag ${s === 'Received' || s === 'Completed' ? 'green' : s === 'Processing' || s === 'On Hold' ? 'amber' : ''}">${esc(s)}</span>`; }

  // ---------- CSSD staff ----------
  function pickMonth(m) { month = m; day = ''; selected = null; render(); }
  function pickDay(d) { day = d; shift = 'ALL'; selected = null; render(); }
  function pickShift(s) { shift = s; selected = null; render(); }
  function selectOrder(id) { selected = id; render(); }
  function staff() { const months = [...new Set(state.orders.map(o => o.date.slice(0, 7)))].sort().reverse(); if (!months.includes(month)) month = months[0] || ''; const dates = [...new Set(state.orders.filter(o => o.date.startsWith(month)).map(o => o.date))].sort(); if (!dates.includes(day)) day = dates[0] || ''; const visible = state.orders.filter(o => o.date === day && (shift === 'ALL' || o.shift === shift)); if (!visible.some(o => o.id === selected)) selected = visible[0]?.id; const o = state.orders.find(x => x.id === selected); const folders = months.map(m => `<button type="button" class="tree ${m === month ? 'active' : ''}"${act('pickMonth', m)}><span><span class="folder">📁</span>${new Date(m + '-15T12:00:00').toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}</span><small>${state.orders.filter(o => o.date.startsWith(m)).length} orders</small></button>${m === month ? `<div class="nested">${dates.map(d => `<button type="button" class="tree ${d === day ? 'active' : ''}"${act('pickDay', d)}><span><span class="folder">📁</span>${esc(d)}</span><small>${state.orders.filter(o => o.date === d).length}</small></button>`).join('')}</div>` : ''}`).join(''); return title('CSSD Staff — Incoming Orders', 'Incoming clinic and OR orders') + staffTaskSummary() + `<div class="grid">` + panel(1, 'Select month folder', `<b>📁 CSSD Incoming Orders</b>${folders || '<p class="empty">No orders</p>'}`) + panel(2, 'Select date and shift', `<p class="muted">${esc(month)} › ${esc(day)}</p>${['ALL', 'AM', 'PM', 'Night'].map(s => `<button type="button" class="tree ${s === shift ? 'active' : ''}"${act('pickShift', s)}><span>📁 ${s === 'ALL' ? 'All Shifts' : s + ' Shift'}</span><small>${state.orders.filter(o => o.date === day && (s === 'ALL' || o.shift === s)).length}</small></button>`).join('')}<div class="tablewrap"><table><thead><tr><th>Order #</th><th>Department</th><th>Time</th><th>Status</th></tr></thead><tbody>${visible.map(x => `<tr tabindex="0" class="clickable ${x.id === selected ? 'selected' : ''}"${act('selectOrder', x.id)}><td>${esc(x.id)}${x.rush ? ' ⚡' : ''}</td><td>${esc(x.dept)}</td><td>${esc(x.time)}</td><td>${statusTag(x.status)}</td></tr>`).join('')}</tbody></table></div>`) + panel(3, 'Order details', o ? `<b>▤ Order # ${esc(o.id)}</b> ${statusTag(o.status)}<div class="meta"><div><b>Department</b>${esc(o.dept)}</div><div><b>Submitted By</b>${esc(o.by)}</div><div><b>Date / Shift</b>${esc(o.date)} / ${esc(o.shift)}</div><div><b>Submission Time</b>${esc(o.time)}</div></div>${o.comment ? `<p class="muted">Department comment: ${esc(o.comment)}</p>` : ''}<div class="tablewrap"><table><thead><tr><th>Instrument</th><th>Requested by Clinic / OR</th><th>Received by CSSD</th><th>Condition</th></tr></thead><tbody>${o.items.map((x, i) => `<tr><td>${esc(x.name)}</td><td>${x.requested}</td><td><input aria-label="Received quantity ${esc(x.name)}" class="qty" type="number" min="0" step="1" data-actual="${i}" value="${x.actual ?? x.requested}"></td><td><select aria-label="Instrument condition" class="condition ${x.condition === 'Good' ? 'good' : 'finding'}" data-condition="${i}">${[...new Set([x.condition || 'Good', 'Good', 'Missing', 'Broken', 'Rust', 'Damaged', 'Other'])].map(c => `<option ${c === (x.condition || 'Good') ? 'selected' : ''}>${esc(c)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>` : `<div class="empty">Select an order to view its details</div>`) + `</div>` + (o ? `<div class="lower">` + panel(4, 'Receiving notes', textarea('rnotes', 'Notes', o.notes) + field('receiver', 'CSSD receiver', 'text', o.receiver || me) + field('witness', 'Witness', 'text', o.witness)) + panel(5, 'Attach file', upload('order', o.id) + files(o.files, 'order', o.id)) + panel(6, 'Change status', `<p>Current Status: ${statusTag(o.status)}</p>` + select('rstatus', 'Update Status', ['New', 'Processing', 'Received', 'Partial Received', 'Completed', 'On Hold', 'Cancelled'], o.status) + `<div class="actions">${btn('✓ Save receiving', 'saveReceiving', true)}</div><p class="muted">Requested quantities remain as submitted by the department.</p>`) + panel(7, 'Order receipt (A4)', `<div id="currentreceipt">${receipt(o)}</div><div class="actions">${btn('Print A4', 'printSelected')}${btn('Download', 'downloadSelected')}</div>`) + `</div>` : ''); }
  function saveReceiving() { const o = state.orders.find(x => x.id === selected); if (!o) return; const numbers = $$('[data-actual]').map(e => Number(e.value)); if (numbers.some(v => !Number.isInteger(v) || v < 0)) { toast('Enter whole, non-negative received quantities.'); return; } o.items.forEach((x, i) => { x.actual = numbers[i]; x.condition = $(`[data-condition="${i}"]`).value; }); Object.assign(o, { notes: $('#rnotes').value, receiver: $('#receiver').value, witness: $('#witness').value, status: $('#rstatus').value, receivedAt: new Date().toISOString() }); persist(); render(); toast('Receiving record saved and order status updated'); }
  function receipt(o) { return `<article class="receipt"><div style="text-align:center"><img class="receipt-logo" src="${esc(logoUrl)}" alt="CSSD Central Hub" width="100" height="56"></div><h3>CSSD CENTRAL HUB</h3><div style="text-align:center">Order receipt</div><div class="rline"><b>Order #</b><span>${esc(o.id)}</span></div><div class="rline"><b>Department</b><span>${esc(o.dept)}</span></div><div class="rline"><b>Date / Shift</b><span>${esc(o.date)} / ${esc(o.shift)}</span></div><div class="rline"><b>Submitted By</b><span>${esc(o.by)}</span></div><div class="rline"><b>CSSD Receiver</b><span>${esc(o.receiver || '—')}</span></div><table><thead><tr><th>Items</th><th>Requested</th><th>Received</th></tr></thead><tbody>${o.items.map(x => `<tr><td>${esc(x.name)}</td><td>${x.requested}</td><td>${o.receivedAt ? x.actual : '—'}</td></tr>`).join('')}<tr><th>TOTAL</th><th>${o.items.reduce((n, x) => n + x.requested, 0)}</th><th>${o.receivedAt ? o.items.reduce((n, x) => n + x.actual, 0) : '—'}</th></tr></tbody></table><div class="rline"><b>Status</b><span>${esc(o.status)}</span></div>${o.notes ? `<p>${esc(o.notes)}</p>` : ''}<div class="barcode" aria-label="Illustrative barcode"></div><div style="text-align:center">${esc(o.id)}<br><small>Illustrative barcode</small></div></article>`; }
  function printOrder(o) { if (o) printHtml(receipt(o)); }
  function printExternalReceipt() { printOrder(externalReceipt); }
  function printSelected() { printOrder(state.orders.find(x => x.id === selected)); }
  function downloadSelected() { const o = state.orders.find(x => x.id === selected); if (!o) return; download(`${o.id}-receipt.html`, `<!doctype html><html lang="en"><meta charset="utf-8"><base href="${esc(document.baseURI)}"><title>${esc(o.id)}</title><style>body{font:14px Arial;max-width:760px;margin:40px auto}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:10px}.rline{display:flex;justify-content:space-between;margin:10px}h3{text-align:center}.receipt-logo{display:block;width:100px;margin:0 auto 8px}.barcode{height:33px;background:repeating-linear-gradient(90deg,#172435 0 2px,white 2px 4px,#172435 4px 5px,white 5px 8px);margin:12px 0}</style>${receipt(o)}</html>`, 'text/html'); }

  // ---------- attachments ----------
  function upload(kind, id) { return `<label class="upload">☁<br>Click to upload file<br><small>PDF, JPG, PNG · up to ${MAX_MB} MB per file</small><input aria-label="Upload file" type="file" accept="application/pdf,image/png,image/jpeg"${chg('attachFile', kind, id)}></label>`; }
  function files(arr, kind, id) { return (arr || []).map((f, i) => `<div class="file"><a href="${esc(f.data)}" target="_blank" rel="noopener" download="${esc(f.name)}">▤ ${esc(f.name)}</a><button type="button" aria-label="Remove attachment"${act('removeFile', kind, id, i)}>×</button></div>`).join(''); }
  function fileTarget(kind, id) { return kind === 'order' ? state.orders.find(x => x.id === id) : kind === 'issue' ? state.issues.find(x => x.id === id) : state.loaners.find(x => x.id === id); }
  async function attachFile(kind, id, input) { if (!input.files[0]) return; try { const draft = kind === 'order' ? receivingDraft() : null; const f = await readFile(input.files[0]), o = fileTarget(kind, id); if (!o) return; o.files ??= []; o.files.push(f); persist(); render(); if (draft && kind === 'order' && selected === id) restoreReceiving(draft); toast('Attachment saved'); } catch (e) { toast(e.message); } }
  function removeFile(kind, id, i) { const o = fileTarget(kind, id); if (!o) return; o.files.splice(i, 1); persist(); render(); toast('Attachment removed'); }
  function receivingDraft() { return { actual: $$('[data-actual]').map(e => e.value), condition: $$('[data-condition]').map(e => e.value), fields: Object.fromEntries(['rnotes', 'receiver', 'witness', 'rstatus'].map(k => [k, $('#' + k)?.value ?? ''])) }; }
  function restoreReceiving(d) { $$('[data-actual]').forEach((e, i) => e.value = d.actual[i]); $$('[data-condition]').forEach((e, i) => e.value = d.condition[i]); for (const [k, v] of Object.entries(d.fields)) { const e = $('#' + k); if (e) e.value = v; } }

  // ---------- issues ----------
  function issues() { return title('Reports / Issues', 'Department reports and issue follow-up') + `<div class="three">` + panel(1, 'Issue details', field('ititle', 'Issue title') + select('itype', 'Issue type', ['Equipment Issue', 'Supply Shortage', 'Workflow Issue', 'Staff Issue', 'Other'], 'Workflow Issue') + field('iauthor', 'Reported by', 'text', me) + field('idate', 'Date', 'date', today())) + panel(2, 'Description and attachments', textarea('idesc', 'Issue description') + textarea('iaction', 'Proposed action') + `<label>Issue attachment (PDF / JPG / PNG, up to ${MAX_MB} MB)</label><input id="ifile" type="file" accept="application/pdf,image/png,image/jpeg">`) + panel(3, 'Follow-up', select('ipriority', 'Priority', ['Normal', 'High', 'Urgent'], 'Normal') + `<p class="muted" dir="ltr">The issue appears below for status tracking and a recorded management response.</p>${btn('Save issue', 'saveIssue', true)}`) + `</div><div class="savedlist">${panel(4, 'Issue records', state.issues.length ? state.issues.map(o => `<article class="record"><h3>${esc(o.title)} ${statusTag(o.status)}</h3><p class="muted">${esc(o.date)} · ${esc(o.type)} · ${esc(o.author)} · ${esc(o.priority)}</p><p>${esc(o.desc)}</p>${o.action ? `<p>Proposed action: ${esc(o.action)}</p>` : ''}${files(o.files, 'issue', o.id)}<label>Issue status</label><select${chg('updateIssue', o.id, 'status')}>${['Open', 'In Review', 'Resolved', 'Closed'].map(s => `<option ${s === o.status ? 'selected' : ''}>${s}</option>`).join('')}</select><label>Management response / Follow-up</label><textarea${chg('updateIssue', o.id, 'response')}>${esc(o.response || '')}</textarea></article>`).join('') : '<p class="empty">No issues yet</p>')}</div>`; }
  let issueSaving = false;
  async function saveIssue() { if (issueSaving) return; const title = $('#ititle').value.trim(), desc = $('#idesc').value.trim(); if (!title || !desc || !$('#iauthor').value.trim()) { toast('Enter the issue title, description and reporter name'); return; } const o = { id: uid(), title, desc, type: $('#itype').value, author: $('#iauthor').value, date: $('#idate').value, action: $('#iaction').value, priority: $('#ipriority').value, status: 'Open', files: [] }; issueSaving = true; try { const f = $('#ifile').files[0]; if (f) o.files.push(await readFile(f)); state.issues.unshift(o); persist(); render(); toast('Issue recorded'); } catch (e) { toast(e.message); } finally { issueSaving = false; } }
  function updateIssue(id, k, el) { const o = state.issues.find(x => x.id === id); if (!o) return; o[k] = el.value; persist(); toast('Issue update saved'); }

  // ---------- in-charge ----------
  function incharge() { return title('In-Charge', 'Shift handover and parameter records') + `<div class="three">` + panel(1, 'Shift handover', field('ename', 'In-charge name', 'text', me) + field('endate', 'Date', 'date', today()) + select('enshift', 'Shift', ['AM', 'PM', 'Night'], 'AM') + textarea('enpending', 'Pending tasks and orders') + textarea('enissues', 'Notes and equipment issues') + field('enreceiver', 'Receiving staff in the next shift') + btn('Save Endorsement', 'saveEndorsement', true)) + panel(2, 'Parameter records', field('pname', 'Staff name', 'text', me) + field('pdevice', 'Device / Area') + field('pcycle', 'Cycle number / Reference') + field('pdate', 'Date', 'date', today()) + field('pparam', 'Parameter name') + field('pvalue', 'Value and unit') + select('presult', 'Result according to department policy', ['Pass', 'Fail', 'Review'], 'Pass') + textarea('pnotes', 'Notes') + btn('Save Parameters', 'saveParameter', true)) + panel(3, 'Workflow follow-up', `<table><thead><tr><th>Status</th><th>Orders</th></tr></thead><tbody>${['New', 'Processing', 'Received', 'Partial Received', 'On Hold', 'Completed'].map(s => `<tr><td>${statusTag(s)}</td><td>${state.orders.filter(o => o.status === s).length}</td></tr>`).join('')}</tbody></table><p>⚡ Rush pending: ${state.orders.filter(o => o.rush && !['Completed', 'Cancelled'].includes(o.status)).length}</p><p>Open issues: ${state.issues.filter(o => !['Closed', 'Resolved'].includes(o.status)).length}</p><p class="muted" dir="ltr">Values are recorded only; assessment follows device instructions and department policy.</p>`) + `</div><div class="three savedlist">` + panel(4, 'Handover records', state.endorsements.map(o => `<div class="record"><b>${esc(o.date)} · ${esc(o.shift)}</b><p>${esc(o.name)} → ${esc(o.receiver)}</p><p>${esc(o.pending)}</p><p>${esc(o.issues)}</p></div>`).join('') || '<p class="empty">No records</p>') + panel(5, 'Parameter records', state.parameters.map(o => `<div class="record"><b>${esc(o.device)} · ${esc(o.date)}</b><p>${esc(o.parameter)}: ${esc(o.value)} ${statusTag(o.result)}</p><p>${esc(o.name)} · ${esc(o.cycle)}</p><p>${esc(o.notes)}</p></div>`).join('') || '<p class="empty">No records</p>') + `</div>`; }
  function saveEndorsement() { if (!$('#ename').value.trim() || !$('#enpending').value.trim()) { toast('Enter the name and shift handover details'); return; } state.endorsements.unshift({ id: uid(), name: $('#ename').value, date: $('#endate').value, shift: $('#enshift').value, pending: $('#enpending').value, issues: $('#enissues').value, receiver: $('#enreceiver').value }); persist(); render(); toast('Saved Endorsement'); }
  function saveParameter() { if (!$('#pname').value.trim() || !$('#pdevice').value.trim() || !$('#pparam').value.trim() || !$('#pvalue').value.trim()) { toast('Enter the staff member, device, parameter and value'); return; } state.parameters.unshift({ id: uid(), name: $('#pname').value, device: $('#pdevice').value, cycle: $('#pcycle').value, date: $('#pdate').value, parameter: $('#pparam').value, value: $('#pvalue').value, result: $('#presult').value, notes: $('#pnotes').value }); persist(); render(); toast('Saved Parameters'); }

  // ---------- loaner sets ----------
  function loaner() { return title('Loaner Sets', 'Loaner set management and tracking') + `<div class="four">` + panel(1, 'Receiving', field('lcompany', 'Company') + field('lset', 'Set name / Set number') + field('lcount', 'Instrument count', 'number') + field('ldate', 'Received at', 'datetime-local', today() + 'T08:00') + field('lreceiver', 'Receiver name', 'text', me)) + panel(2, 'Inspection', textarea('lcontents', 'Set contents and quantities') + textarea('lcondition', 'Inspection findings and shortages') + `<label>File / Image (up to ${MAX_MB} MB)</label><input id="lfile" type="file" accept="application/pdf,image/png,image/jpeg">`) + panel(3, 'Processing and delivery', field('lcycle', 'Sterilization cycle reference') + field('lrelease', 'Delivery date and time', 'datetime-local') + field('lto', 'Delivered to') + textarea('lnotes', 'Notes')) + panel(4, 'Return and tracking', select('lstatus', 'Set status', ['Received', 'Inspection', 'Processing', 'Sterilized', 'Delivered', 'Returned'], 'Received') + field('lreturn', 'Return date and time', 'datetime-local') + field('lreturnedto', 'Received by on return') + btn('Save Loaner Set', 'saveLoaner', true)) + `</div><div class="savedlist">${panel(5, 'Loaner records', state.loaners.map(o => `<article class="record"><h3>${esc(o.set)} · ${esc(o.company)}</h3><div class="meta"><div><b>Received</b>${esc(o.date)} · ${esc(o.receiver)}</div><div><b>Instrument count</b>${o.count}</div><div><b>Sterilization cycle</b>${esc(o.cycle || '—')}</div><div><b>Delivery</b>${esc(o.release || '—')} · ${esc(o.to)}</div></div><p>${esc(o.contents)}</p><p>Inspection: ${esc(o.condition)}</p><p>${esc(o.notes)}</p><label>Update status</label><select${chg('updateLoaner', o.id, 'status')}>${['Received', 'Inspection', 'Processing', 'Sterilized', 'Delivered', 'Returned'].map(s => `<option ${s === o.status ? 'selected' : ''}>${s}</option>`).join('')}</select><label>Sterilization cycle reference</label><input value="${esc(o.cycle)}"${chg('updateLoaner', o.id, 'cycle')}><label>Delivery date and time</label><input type="datetime-local" value="${esc(o.release)}"${chg('updateLoaner', o.id, 'release')}><label>Delivered to</label><input value="${esc(o.to)}"${chg('updateLoaner', o.id, 'to')}><label>Return date and time</label><input type="datetime-local" value="${esc(o.returnDate)}"${chg('updateLoaner', o.id, 'returnDate')}><label>Received by on return</label><input value="${esc(o.returnedTo)}"${chg('updateLoaner', o.id, 'returnedTo')}>${files(o.files, 'loaner', o.id)}${upload('loaner', o.id)}</article>`).join('') || '<p class="empty">No loaner sets yet</p>')}</div>`; }
  let loanerSaving = false;
  async function saveLoaner() { if (loanerSaving) return; const count = Number($('#lcount').value); if (!$('#lcompany').value.trim() || !$('#lset').value.trim() || !$('#lreceiver').value.trim() || !Number.isInteger(count) || count < 1) { toast('Enter the company, set, receiver and a valid whole instrument count'); return; } const o = { id: uid(), company: $('#lcompany').value, set: $('#lset').value, count, date: $('#ldate').value, receiver: $('#lreceiver').value, contents: $('#lcontents').value, condition: $('#lcondition').value, cycle: $('#lcycle').value, release: $('#lrelease').value, to: $('#lto').value, notes: $('#lnotes').value, status: $('#lstatus').value, returnDate: $('#lreturn').value, returnedTo: $('#lreturnedto').value, files: [] }; loanerSaving = true; try { const f = $('#lfile').files[0]; if (f) o.files.push(await readFile(f)); state.loaners.unshift(o); persist(); render(); toast('Record saved for Loaner Set'); } catch (e) { toast(e.message); } finally { loanerSaving = false; } }
  function updateLoaner(id, k, el) { const o = state.loaners.find(x => x.id === id); if (!o) return; o[k] = el.value; persist(); toast('Set record updated'); }

  // ---------- department management ----------
  let managementFilter = { from: '', to: '', dept: 'All', shift: 'All' };
  const CLOSED_ORDERS = ['Completed', 'Cancelled'];
  function managementData() { return state.management; }
  function managementOrders() { const f = managementFilter; return state.orders.filter(o => (!f.from || o.date >= f.from) && (!f.to || o.date <= f.to) && (f.dept === 'All' || o.dept === f.dept) && (f.shift === 'All' || o.shift === f.shift)); }
  function managementTaskRows(tasks) { return tasks.map(t => `<tr><td><b>${esc(t.title)}</b><small>${esc(t.note)}</small></td><td>${esc(t.owner)}</td><td>${esc(t.date)}<br>${esc(t.shift)}</td><td><select aria-label="Task status"${chg('updateManagementTask', t.id)}>${['Not started', 'In progress', 'Completed', 'On hold'].map(v => `<option ${v === t.status ? 'selected' : ''}>${v}</option>`).join('')}</select></td></tr>`).join('') || '<tr><td colspan="4">No tasks in the selected period</td></tr>'; }
  function managementMetrics(orders) {
    const reviewed = orders.filter(o => o.receivedAt), requested = orders.reduce((s, o) => s + o.items.reduce((n, x) => n + Number(x.requested || 0), 0), 0);
    const actual = reviewed.reduce((s, o) => s + o.items.reduce((n, x) => n + Number(x.actual || 0), 0), 0);
    const missing = reviewed.reduce((s, o) => s + o.items.reduce((n, x) => n + Math.max(0, Number(x.requested) - Number(x.actual)), 0), 0);
    const mismatch = reviewed.filter(o => o.items.some(x => Number(x.actual) !== Number(x.requested) || x.condition !== 'Good')).length;
    return { total: orders.length, pending: orders.filter(o => !CLOSED_ORDERS.includes(o.status)).length, rush: orders.filter(o => o.rush && !CLOSED_ORDERS.includes(o.status)).length, reviewed: reviewed.length, requested, actual, missing, mismatch };
  }
  function managementBars(orders) { const groups = Object.entries(orders.reduce((a, o) => (a[o.status] = (a[o.status] || 0) + 1, a), {})); const max = Math.max(1, ...groups.map(x => x[1])); return groups.map(([s, n]) => `<div class="management-bar"><span>${esc(s)}</span><div><i style="width:${n / max * 100}%"></i></div><b>${n}</b></div>`).join('') || '<p class="empty">No orders match the filters</p>'; }
  function managementPage() {
    const a = managementData(), orders = managementOrders(), m = managementMetrics(orders), f = managementFilter;
    const dept = ['All', ...new Set(state.orders.map(o => o.dept))];
    const taskRows = a.tasks.filter(t => (!f.from || t.date >= f.from) && (!f.to || t.date <= f.to) && (f.shift === 'All' || t.shift === f.shift));
    const openIssues = state.issues.filter(x => !['Closed', 'Resolved'].includes(x.status));
    const activeLoaners = state.loaners.filter(x => x.status !== 'Returned');
    return title('Department Management', 'Department management and dashboard') + `<div class="management" dir="ltr"><div class="impact-intro"><div><h2>Department operations at a glance</h2><p>Orders, receiving, issues, shift handovers and loaner sets use the same site records. Task assignments and device status are recorded manually below.</p></div><div class="impact-credit"><b>Initiative by Shrooq Almeshari</b><p>Shared records on this SharePoint site</p><small>Access follows SharePoint permissions. Site owners can restrict the management lists (CSSD Staff Tasks, CSSD Device Status) to the In-Charge and management group.</small></div></div><p class="demo">Loads and results for BI are not linked automatically to SPM. Calculate productivity or savings only from validated records.</p>
 <form class="management-filters"${sub('applyManagementFilter')}>${detailField('mf-from', 'Orders and tasks from', f.from, 'date')}${detailField('mf-to', 'To date', f.to, 'date')}${select('mf-dept', 'Ordering department', dept, f.dept)}${select('mf-shift', 'Shift', ['All', 'AM', 'PM', 'Night'], f.shift)}<div class="actions"><button type="submit" class="primary">Apply</button>${btn('All dates', 'resetManagementFilter')}</div></form>
 <div class="management-kpis">${[['Orders', m.total], ['Open orders', m.pending], ['Open urgent orders', m.rush], ['Orders with documented receiving', m.reviewed], ['Requested item quantity', m.requested], ['Documented received item quantity', m.actual], ['Documented quantity shortage', m.missing], ['Orders with discrepancies or findings', m.mismatch]].map(([l, n]) => `<div><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><p class="muted">Counts refer to orders within the selected filters. Receiving, shortages and discrepancies are counted only after receiving is saved; order status alone does not confirm the received quantity. Counts reflect entered item quantities, which may include sets.</p>
 <div class="management-grid">${panel(1, 'Orders by status', managementBars(orders) + `<div class="actions">${btn('Open incoming orders', 'go', false, 'staff')}${btn('Emergency cases', 'go', false, 'emergency')}${btn('Recall and OR follow-up', 'go', false, 'recall')}</div>`)}
 ${panel(2, 'Orders requiring follow-up', `<div class="tablewrap"><table><thead><tr><th>Order and department</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody>${orders.filter(o => !CLOSED_ORDERS.includes(o.status)).sort((a, b) => Number(b.rush) - Number(a.rush) || a.date.localeCompare(b.date)).map(o => `<tr><td>${o.rush ? '⚡ ' : ''}${esc(o.id)}<small>${esc(o.dept)}</small></td><td>${esc(o.date)}<br>${esc(o.shift)}</td><td>${statusTag(o.status)}</td><td>${btn('Open', 'openIncoming', false, o.id)}</td></tr>`).join('') || '<tr><td colspan="4">No open orders match the filters</td></tr>'}</tbody></table></div>`)}
 ${panel(3, 'Staff task assignment and shift follow-up', `<form${sub('saveManagementTask')}>${detailField('mt-title', 'Task', '', 'text', 'required')}${detailField('mt-owner', 'Assigned staff member', '', 'text', 'required')}<div class="impact-fields">${detailField('mt-date', 'Task date', today(), 'date', 'required')}${select('mt-shift', 'Shift', ['AM', 'PM', 'Night'], 'AM')}</div>${textarea('mt-note', 'Task details or order reference')}<button class="primary" type="submit">Assign and save task</button></form><p class="muted">The same tasks appear on the CSSD staff screen and their status can be updated there. Assigning a task does not send an external notification.</p><div class="tablewrap"><table><thead><tr><th>Task</th><th>Responsible person</th><th>Due date</th><th>Status</th></tr></thead><tbody>${managementTaskRows(taskRows)}</tbody></table></div>`)}
 ${panel(4, 'Device readiness and follow-up', `<form${sub('saveManagementDevice')}>${detailField('md-name', 'Device name or number', '', 'text', 'required')}${select('md-status', 'Recorded status', ['Available', 'Out of service', 'Under maintenance', 'Awaiting verification'], 'Awaiting verification')}${detailField('md-author', 'Updated by', me, 'text', 'required')}${textarea('md-note', 'Notes and maintenance reference, if available')}<button class="primary" type="submit">Save device status</button></form><p class="muted">Entering the same device name updates its record. This is manual follow-up, not authorization for use or load release. Create maintenance requests in the approved hospital system.</p>${a.devices.map(v => `<article class="record"><h3>${esc(v.name)} <span class="tag ${v.status === 'Available' ? 'green' : 'amber'}">${esc(v.status)}</span></h3><p>${esc(v.note)}</p><small>${esc(v.author)} · ${esc(v.updatedAt.slice(0, 16).replace('T', ' '))} UTC</small></article>`).join('') || '<p class="empty">No device status records</p>'}`)}
 ${panel(5, 'Quality, issues and loaner sets', `<p><b>${openIssues.length}</b> open issues · <b>${activeLoaners.length}</b> loaner sets not yet returned · <b>${emergencyData().filter(x => x.status !== 'Closed').length}</b> emergency cases in follow-up · <b>${recallData().filter(x => ['Recall activated', 'In follow-up'].includes(x.status)).length}</b> active recalls in follow-up.</p><p class="muted">These counts include all records and are not affected by the order and shift filters above.</p>${openIssues.slice(0, 5).map(x => `<div class="record"><b>${esc(x.title)}</b><p>${esc(x.date)} · ${esc(x.priority)} · ${statusTag(x.status)}</p></div>`).join('') || '<p>No open issues.</p>'}<div class="actions">${btn('Issues and response tracking', 'go', false, 'issues')}${btn('Loaner set records', 'go', false, 'loaner')}</div>`)}
 ${panel(6, 'Shift handover and management report', `<p class="muted">Latest 3 handover records from all shifts, without the order filters.</p>${state.endorsements.slice(0, 3).map(x => `<article class="record"><b>${esc(x.date)} · ${esc(x.shift)}</b><p>${esc(x.name)} ← ${esc(x.receiver)}</p><p>${esc(x.pending)}</p><p>${esc(x.issues)}</p></article>`).join('') || '<p>No shift handover recorded yet.</p>'}<p>Parameter records in this site: <b>${state.parameters.length}</b>. Records are displayed as entered by staff and are not interpreted automatically.</p><div class="actions">${btn('Handover and parameter records', 'go', false, 'incharge')}${btn('Print management summary', 'printManagementReport', true)}</div><p class="muted">Tracking orders and tasks supports work organization and follow-up.</p>`)}
 </div></div>`;
  }
  function applyManagementFilter() { const f = { from: $('#mf-from').value, to: $('#mf-to').value, dept: $('#mf-dept').value, shift: $('#mf-shift').value }; if (f.from && f.to && f.to < f.from) { toast('The end date must not precede the start date'); return; } managementFilter = f; render(); }
  function resetManagementFilter() { managementFilter = { from: '', to: '', dept: 'All', shift: 'All' }; render(); }
  function saveManagementTask() {
    const v = { id: uid(), title: $('#mt-title').value.trim(), owner: $('#mt-owner').value.trim(), date: $('#mt-date').value, shift: $('#mt-shift').value, note: $('#mt-note').value.trim(), status: 'Not started', createdAt: new Date().toISOString() };
    if (!v.title || !v.owner || !v.date) { toast('Complete the task, responsible person and date'); return; }
    managementData().tasks.unshift(v); persist(); render(); toast('Task saved and visible on the staff screen');
  }
  function updateManagementTask(id, el) { const status = el.value; if (!['Not started', 'In progress', 'Completed', 'On hold'].includes(status)) return; const t = managementData().tasks.find(x => x.id === id); if (!t) return; const draft = page === 'staff' ? receivingDraft() : null; t.status = status; t.updatedAt = new Date().toISOString(); persist(); render(); if (draft) restoreReceiving(draft); toast('Task status updated'); }
  function saveManagementDevice() {
    const v = { name: $('#md-name').value.trim(), status: $('#md-status').value, author: $('#md-author').value.trim(), note: $('#md-note').value.trim(), updatedAt: new Date().toISOString() };
    if (!v.name || !v.author) { toast('Enter the device name and recorder'); return; }
    const a = managementData(), old = a.devices.find(x => x.name === v.name); if (old) Object.assign(old, v); else a.devices.unshift({ id: uid(), ...v });
    persist(); render(); toast('Device status saved');
  }
  function staffTaskSummary() {
    const tasks = managementData().tasks.filter(t => t.date === day && (shift === 'ALL' || t.shift === shift));
    return `<section class="staff-tasks" dir="ltr"><div class="sectiontitle"><b>Staff tasks for ${esc(day || 'selected date')} ${shift === 'ALL' ? '· All shifts' : '· ' + esc(shift)}</b>${btn('Department management and dashboard', 'go', false, 'management')}</div><div class="tablewrap"><table><thead><tr><th>Task</th><th>Responsible person</th><th>Due date</th><th>Status</th></tr></thead><tbody>${managementTaskRows(tasks)}</tbody></table></div></section>`;
  }
  function printManagementReport() {
    const orders = managementOrders(), m = managementMetrics(orders), f = managementFilter;
    printHtml(`<article class="impact-report" dir="ltr"><h1>CSSD Central Hub</h1><h2>Department management summary</h2><p>Initiative by Shrooq Almeshari · ${esc(today())}</p><p>Period ${esc(f.from || 'All')} to ${esc(f.to || 'All')} · Department ${esc(f.dept)} · Shift ${esc(f.shift)}</p><p>This report reflects the records entered in the CSSD SharePoint lists.</p><table><thead><tr><th>Indicator</th><th>Count</th></tr></thead><tbody>${[['Orders', m.total], ['Open', m.pending], ['Open urgent orders', m.rush], ['Documented receiving', m.reviewed], ['Requested quantities', m.requested], ['Documented received quantities', m.actual], ['Documented shortage', m.missing], ['Orders with discrepancies or findings', m.mismatch]].map(([k, n]) => `<tr><td>${k}</td><td>${n}</td></tr>`).join('')}</tbody></table><p>Shortages and discrepancies are calculated only from saved receiving records. Quantities are not individual instrument counts when an item is a set.</p><h3>Order statuses</h3>${managementBars(orders)}<h3>Follow-up notes</h3><p>Open issues across all records: ${state.issues.filter(x => !['Closed', 'Resolved'].includes(x.status)).length}. Loaner sets not yet returned across all records: ${state.loaners.filter(x => x.status !== 'Returned').length}.</p><p>These counts come from site records and support department follow-up.</p></article>`);
  }

  // ---------- IFU library ----------
  let ifuQuery = '', ifuEditing = null, ifuSaving = false;
  function ifuData() { return state.ifuDocuments; }
  function ifuURL(value) { if (!value) return ''; try { const u = new URL(value); if (u.protocol !== 'https:' || u.username || u.password) throw Error(); return u.href; } catch (e) { throw Error('Enter a valid HTTPS link'); } }
  function ifuFiltered() { const q = ifuQuery.trim().toLowerCase(); return ifuData().filter(r => r.status !== 'Replaced or archived' && (!q || [r.title, r.manufacturer, r.model].some(v => String(v || '').toLowerCase().includes(q)))); }
  function ifuCard(r) { let url = ''; try { url = ifuURL(r.sourceURL || ''); } catch (e) { } return `<article class="ifu-card"><h3>${esc(r.title)}</h3>${r.manufacturer || r.model ? `<p class="muted">${esc(r.manufacturer || '')}${r.manufacturer && r.model ? ' · ' : ''}${esc(r.model || '')}</p>` : ''}<div class="actions">${r.file ? `<a class="ifu-link primary" href="${esc(r.file.data)}" target="_blank" rel="noopener">Open IFU file</a>` : ''}${url ? `<a class="ifu-link primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open IFU ↗</a>` : ''}${btn('Edit', 'editIFUDocument', false, r.id)}</div></article>`; }
  function ifuLibraryPage() { const editing = ifuData().find(r => r.id === ifuEditing), rows = ifuFiltered(); return title('IFU Library', 'Instructions for use library') + `<div class="ifu-library ifu-simple" dir="ltr"><div class="ifu-layout"><div>${panel(1, editing ? 'Edit IFU' : 'Add IFU', `<form${sub('saveIFUDocument')}>${detailField('ifu-title', 'Instrument name', editing?.title || '', 'text', 'required placeholder="Enter the instrument name" maxlength="180"')}<label>IFU file<input id="ifu-file" type="file" accept="application/pdf,image/png,image/jpeg"></label>${editing?.file ? `<small class="muted">Current file: ${esc(editing.file.name)}. Upload another file to replace it.</small>` : ''}${detailField('ifu-sourceURL', 'IFU link', editing?.sourceURL || '', 'url', 'placeholder="https://"')}<details><summary>Company and model are optional</summary>${detailField('ifu-manufacturer', 'Company', editing?.manufacturer || '')}${detailField('ifu-model', 'Model or REF', editing?.model || '')}</details><p class="muted">PDF or an image up to ${MAX_MB} MB. A file or link is sufficient.</p><div class="actions"><button type="submit" class="primary">${editing ? 'Save changes' : 'Save IFU'}</button>${editing ? btn('Cancel', 'cancelIFUEdit') : ''}</div></form>`)}</div><div>${panel(2, 'Find an instrument', `<form${sub('searchIFULibrary')}><label for="ifu-query">Instrument name</label><div class="ifu-search-line"><input id="ifu-query" value="${esc(ifuQuery)}" placeholder="Search for an instrument"><button class="primary" type="submit">Search</button>${ifuQuery ? btn('All', 'resetIFULibrary') : ''}</div></form>`)}<div class="ifu-results impact-gap">${rows.map(ifuCard).join('') || `<div class="panel empty">${ifuQuery ? 'No matching instrument.' : 'Add an instrument name and its IFU to display it here.'}</div>`}</div><p class="muted">${rows.length} results · Files are stored in the CSSD Attachments library. Ensure the file matches the instrument and model.</p></div></div></div>`; }
  async function saveIFUDocument() { if (ifuSaving) return; const id = ifuEditing, title = $('#ifu-title').value.trim(), manufacturer = $('#ifu-manufacturer').value.trim(), model = $('#ifu-model').value.trim(), link = $('#ifu-sourceURL').value.trim(), file = $('#ifu-file').files[0], previous = ifuData().find(x => x.id === id); if (!title) { toast('Enter the instrument name'); return; } ifuSaving = true; try { const sourceURL = ifuURL(link); if (!file && !sourceURL && !previous?.file) { toast('Add the IFU file or its link'); return; } const attachment = file ? await readFile(file) : previous?.file; const record = { ...(previous || {}), id: previous?.id || uid(), title, manufacturer, model, sourceURL, file: attachment, updatedAt: new Date().toISOString() }; const at = ifuData().findIndex(x => x.id === id); if (at >= 0) state.ifuDocuments[at] = record; else ifuData().unshift(record); persist(); ifuEditing = null; render(); toast('Saved IFU'); } catch (e) { toast(e.message); } finally { ifuSaving = false; } }
  function searchIFULibrary() { ifuQuery = $('#ifu-query').value.trim(); render(); }
  function editIFUDocument(id) { ifuEditing = id; render(); scrollTop(); }
  function cancelIFUEdit() { ifuEditing = null; render(); }
  function resetIFULibrary() { ifuQuery = ''; render(); }

  // ---------- emergency cases ----------
  const EMERGENCY_STATUSES = ['Recorded', 'In follow-up', 'Closed'];
  const EMERGENCY_STAGES = ['Not verified', 'Cleaning incomplete', 'Disinfection incomplete', 'Sterilization incomplete', 'Awaiting results or release', 'Complete according to the documented record'];
  let emergencySearch = '';
  function emergencyData() { return state.emergencies; }
  function emergencyNow() { return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Riyadh', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date()).replace(' ', 'T'); }
  function emergencySafety() { return '<p class="emergency-safety">This is a documentation and follow-up record, not authorization to use an instrument or confirmation of its suitability. An emergency or lack of an alternative does not make incomplete processing complete. Follow hospital policy, manufacturer instructions and the approved escalation process.</p>'; }
  function emergencyFiltered() { const q = emergencySearch.trim().toLowerCase(); return emergencyData().filter(r => !q || [r.id, r.dept, r.set, r.caseRef, r.status].some(v => String(v || '').toLowerCase().includes(q))); }
  function emergencyRecord(r) { return `<article class="record emergency-record"><div class="sectiontitle"><h3>${esc(r.set)} · ${esc(r.id)}</h3><span class="tag ${r.status === 'Closed' ? 'green' : 'amber'}">${esc(r.status)}</span></div><div class="meta"><div><b>Department and time</b>${esc(r.dept)} · ${esc(r.at.replace('T', ' '))}</div><div><b>Set requester and recorder</b>${esc(r.requester)} · ${esc(r.recorder)}</div><div><b>Requested quantity</b>${r.quantity}</div><div><b>Demo case reference</b>${esc(r.caseRef || 'Not added')}</div></div><p><b>Condition at request time:</b> ${esc(r.stage)}${r.noAlternative ? ' · No alternative set available, as reported' : ''}</p><p><b>Reason for urgency and current situation:</b> ${esc(r.situation)}</p>${r.processRef ? `<p>Reference SPM or load: ${esc(r.processRef)}</p>` : ''}${r.contacted ? `<p><b>Recorded contact:</b> ${esc(r.contacted)} · ${esc(r.contactRole)} · ${esc(r.contactAt.replace('T', ' '))}</p>` : '<p class="muted">No contact recorded yet.</p>'}${r.initialAction ? `<p>Documented action: ${esc(r.initialAction)}</p>` : ''}${r.file ? `<a class="ifu-link" href="${esc(r.file.data)}" target="_blank" rel="noopener">Open attachment</a>` : ''}<details><summary>Recorded follow-up (${r.events.length})</summary>${r.events.map(e => `<div class="emergency-event"><b>${esc(e.status)}</b> · ${esc(e.actor)}<small>${esc(e.at)}</small><p>${esc(e.note)}</p></div>`).join('') || '<p>No follow-up added.</p>'}</details>${r.status !== 'Closed' ? `<form${sub('addEmergencyFollowup', r.id)}><div class="emergency-followup">${select('em-status-' + r.id, 'Update follow-up status', EMERGENCY_STATUSES, r.status)}${detailField('em-actor-' + r.id, 'Follow-up recorded by', me, 'text', 'required')}${textarea('em-note-' + r.id, 'Action taken or follow-up outcome')}</div><button type="submit">Save follow-up</button><p class="muted">Closing the record completes documentation and follow-up only; it does not approve instrument suitability or clinical treatment.</p></form>` : '<p class="muted">The follow-up record is closed; original details are retained.</p>'}<div class="actions">${btn('Print case record', 'printEmergency', false, r.id)}</div></article>`; }
  function emergencyPage() { const rows = emergencyFiltered(); return title('Emergency Cases', 'Emergency cases') + `<div class="emergency-page" dir="ltr"><p class="emergency-intro">Document an urgent instrument or set request, its processing status, lack of an alternative, contacts and actions taken.</p>${emergencySafety()}<p class="muted">Do not enter real patient names or medical record numbers; the optional case reference accepts DEMO- only. Saving does not send a notification or contact any responsible person.</p><form${sub('saveEmergency')}><div class="emergency-grid">${panel(1, 'Emergency request details', detailField('em-dept', 'Requesting department', '', 'text', 'required placeholder="Emergency Department or OR"') + detailField('em-at', 'Request time', emergencyNow(), 'datetime-local', 'required') + detailField('em-requester', 'Instrument or set requested by', '', 'text', 'required') + detailField('em-recorder', 'Case recorded by', me, 'text', 'required') + detailField('em-caseRef', 'Optional demo case reference', '', 'text', 'placeholder="DEMO-CASE-001" pattern="DEMO-[A-Z0-9-]{1,40}"'))}${panel(2, 'Instrument and condition at request time', detailField('em-set', 'Instrument or set name', '', 'text', 'required') + detailField('em-quantity', 'Requested quantity', '1', 'number', 'required min="1" step="1"') + select('em-stage', 'Processing status at request time', EMERGENCY_STAGES, EMERGENCY_STAGES[0]) + `<label><input id="em-noAlternative" type="checkbox"> No alternative set available, as reported</label>` + detailField('em-processRef', 'Reference SPM or load, if available') + textarea('em-situation', 'Reason for urgency and current situation'))}${panel(3, 'Contacts and documented action', detailField('em-contacted', 'Contact person') + detailField('em-contactRole', 'Role or department') + detailField('em-contactAt', 'Contact time', '', 'datetime-local') + textarea('em-initialAction', 'Action taken or response still pending') + `<label>Optional attachment<input id="em-file" type="file" accept="application/pdf,image/jpeg,image/png"></label><small class="muted">PDF or an image up to ${MAX_MB} MB.</small><div class="actions"><button class="primary" type="submit">Save emergency case</button></div>`)}</div></form><div class="savedlist">${panel(4, 'Case records and follow-up', `<form${sub('searchEmergencies')}><label for="em-search">Search by department, set or case reference</label><div class="ifu-search-line"><input id="em-search" value="${esc(emergencySearch)}"><button class="primary" type="submit">Search</button>${btn('All', 'resetEmergencySearch')}</div></form><p class="muted">${rows.length} records · Processing status reflects the time of request and is not updated automatically from SPM.</p>${rows.map(emergencyRecord).join('') || '<p class="empty">No cases recorded.</p>'}`)}</div><p class="muted"><a href="https://www.cdc.gov/infection-control/hcp/disinfection-sterilization/summary-recommendations.html" target="_blank" rel="noopener noreferrer">General reference for cleaning, disinfection and sterilization requirements — CDC</a></p></div>`; }
  let emergencySaving = false;
  async function saveEmergency() {
    if (emergencySaving) return; const r = { id: 'EM-' + uid(), status: 'Recorded', events: [], createdAt: new Date().toISOString() }; for (const k of ['dept', 'at', 'requester', 'recorder', 'caseRef', 'set', 'quantity', 'stage', 'processRef', 'situation', 'contacted', 'contactRole', 'contactAt', 'initialAction']) r[k] = $('#em-' + k).value.trim(); r.quantity = Number(r.quantity); r.noAlternative = $('#em-noAlternative').checked;
    if (!r.dept || !r.at || !r.requester || !r.recorder || !r.set || !r.situation || !Number.isInteger(r.quantity) || r.quantity < 1 || !EMERGENCY_STAGES.includes(r.stage)) { toast('Complete the request details, set and situation, with a valid whole quantity'); return; }
    if (r.caseRef && !/^DEMO-[A-Z0-9-]{1,40}$/.test(r.caseRef)) { toast('Use a demo reference starting with DEMO-, or leave the field blank'); return; }
    if (!Number.isFinite(+new Date(r.at)) || r.at > emergencyNow() || (r.contactAt && (!Number.isFinite(+new Date(r.contactAt)) || r.contactAt < r.at || r.contactAt > emergencyNow()))) { toast('Check the dates: Dates cannot be in the future, and contact cannot precede the request'); return; }
    if ([r.contacted, r.contactRole, r.contactAt].some(Boolean) && ![r.contacted, r.contactRole, r.contactAt].every(Boolean)) { toast('When recording a contact, complete the name, role and contact time'); return; }
    emergencySaving = true; try { const f = $('#em-file').files[0]; if (f) r.file = await readFile(f); emergencyData().unshift(r); persist(); render(); toast('Case recorded for documentation; no notification or authorization for use was issued'); } catch (e) { toast(e.message); } finally { emergencySaving = false; }
  }
  function addEmergencyFollowup(id) { const r = emergencyData().find(x => x.id === id); if (!r || r.status === 'Closed') return; const status = $('#em-status-' + id).value, actor = $('#em-actor-' + id).value.trim(), note = $('#em-note-' + id).value.trim(); if (!EMERGENCY_STATUSES.includes(status) || !actor || !note) { toast('Enter the follow-up recorder and action taken before saving or closing'); return; } r.status = status; r.events.push({ status, actor, note, at: new Date().toISOString() }); persist(); render(); toast('Case follow-up saved; closing does not confirm instrument suitability'); }
  function searchEmergencies() { emergencySearch = $('#em-search').value.trim(); render(); }
  function resetEmergencySearch() { emergencySearch = ''; render(); }
  function printEmergency(id) { const r = emergencyData().find(x => x.id === id); if (!r) return; printHtml(`<article class="impact-report" dir="ltr"><h1>CSSD Central Hub</h1><h2>Emergency case record</h2><p>Initiative by Shrooq Almeshari</p>${emergencySafety()}<p>Reference ${esc(r.id)} · ${esc(r.status)}<br>Department ${esc(r.dept)} · Time ${esc(r.at.replace('T', ' '))}<br>Instrument requester ${esc(r.requester)} · Case recorder ${esc(r.recorder)}<br>Demo case reference ${esc(r.caseRef || 'Not added')}</p><h3>Situation at request time</h3><p>${esc(r.set)} · Quantity ${r.quantity}<br>Processing status ${esc(r.stage)}<br>Alternative set ${r.noAlternative ? 'Unavailable, as reported' : 'Unavailability was not recorded'}<br>Processing reference ${esc(r.processRef || 'Not added')}<br>${esc(r.situation)}</p><h3>Contact and action</h3><p>${r.contacted ? esc(r.contacted) + ' · ' + esc(r.contactRole) + ' · ' + esc(r.contactAt) : 'No contact recorded'}<br>${esc(r.initialAction || 'No action documented yet')}</p><h3>Follow-up</h3>${r.events.map(e => `<p><b>${esc(e.status)}</b> · ${esc(e.actor)} · ${esc(e.at)}<br>${esc(e.note)}</p>`).join('') || '<p>No follow-up added.</p>'}<p>Attachment ${esc(r.file?.name || 'None')}. Review processing records and results in the approved system.</p></article>`); }

  // ---------- recall ----------
  const RECALL_REASONS = ['BI result requiring review', 'Chemical indicator (CI) failure', 'Cycle parameter failure', 'Instrument or packaging issue', 'Manufacturer notice', 'Other reason'];
  const RECALL_OR_RESULTS = ['Review not started', 'Reviewing OR records', 'No use recorded in the reviewed records', 'Use linked in the patient record', 'Set remains in the department and was not used', 'Insufficient information'];
  let recallQuery = '', orRecallQuery = '';
  function recallData() { return state.recalls; }
  function parseRecallItems(text) { const rows = text.split('\n').map(x => x.trim()).filter(Boolean); if (!rows.length) throw Error('Add the pack barcode and set name'); const items = rows.map(line => { const at = line.indexOf('|'); if (at < 1 || !line.slice(at + 1).trim()) throw Error('For each set, enter the barcode, then | then the set name'); const barcode = line.slice(0, at).trim(), name = line.slice(at + 1).trim(); if (barcode.length > 120 || name.length > 180) throw Error('The barcode or set name is too long'); return { id: uid(), barcode, name, orEvents: [] }; }); if (new Set(items.map(x => x.barcode)).size !== items.length) throw Error('A barcode is duplicated in the list'); return items; }
  function recallMatch(r, q) { return !q || [r.id, r.reason, r.device, r.load, r.processDate, ...r.items.flatMap(x => [x.barcode, x.name])].some(x => String(x || '').toLowerCase().includes(q.toLowerCase())); }
  function recallActive() { return recallData().filter(r => ['Recall activated', 'In follow-up', 'Closed'].includes(r.status)); }
  function recallTable(r, ops = false, print = false) { return `<div class="tablewrap"><table><thead><tr><th>Pack barcode</th><th>Set name</th><th>OR follow-up</th><th>Entered association count</th>${ops && !print ? '<th>Add review outcome</th>' : ''}</tr></thead><tbody>${r.items.map(x => { const last = x.orEvents.at(-1); return `<tr><td dir="ltr">${esc(x.barcode)}</td><td>${esc(x.name)}</td><td>${esc(last?.result || 'Review not started')}${last ? `<small>${esc(last.actor)} · ${esc(last.at)}<br>${esc(last.note)}</small>` : ''}</td><td>${last?.count === null || last?.count === undefined ? 'Not specified' : last.count}${last?.ref ? `<small>${esc(last.ref)}</small>` : ''}</td>${ops && !print ? `<td>${r.status !== 'Closed' ? `<details><summary>Record follow-up</summary><form${sub('saveRecallOR', r.id, x.id)}>${select('ro-result-' + x.id, 'Search outcome', RECALL_OR_RESULTS, last?.result || RECALL_OR_RESULTS[0])}${detailField('ro-count-' + x.id, 'Number of patient associations, if known', '', 'number', 'step="1"')}${detailField('ro-actor-' + x.id, 'OR recorder', me, 'text', 'required')}${detailField('ro-ref-' + x.id, 'Optional demo follow-up reference', '', 'text', 'placeholder="DEMO-OR-001"')}${textarea('ro-note-' + x.id, 'Records reviewed and actions taken')}<button type="submit">Save OR response</button></form></details>` : 'Record closed'}</td>` : ''}</tr>`; }).join('')}</tbody></table></div>`; }
  function recallRecord(r, ops = false) { return `<article class="record recall-record"><div class="sectiontitle"><h3>${esc(r.id)}</h3><span class="tag ${r.status === 'Closed' ? 'green' : 'amber'}">${esc(r.status)}</span></div><p><b>Reason:</b> ${esc(r.reason)} · ${esc(r.method)}<br><b>Load:</b> ${esc(r.load)} · <b>Device:</b> ${esc(r.device)} · <b>Processing date:</b> ${esc(r.processDate)}</p><p><b>Defined scope:</b> ${esc(r.scope)}</p><p>${esc(r.details)}</p>${r.authorizer ? `<p class="muted">Activation recorded by ${esc(r.authorizer)} · Reference ${esc(r.decisionRef)}<br>${esc(r.decision)}</p>` : '<p class="muted">Under review; recall not activated.</p>'}${recallTable(r, ops)}${r.file ? `<a class="ifu-link" href="${esc(r.file.data)}" target="_blank" rel="noopener">Issue attachment</a>` : ''}${!ops && r.status === 'Under review' ? `<details><summary>Record recall decision</summary><form${sub('decideRecall', r.id)}>${select('rc-decision-status-' + r.id, 'Recorded decision', ['Recall activated', 'Recall not authorized'], 'Recall activated')}${detailField('rc-authorizer-' + r.id, 'Authorized decision-maker', '', 'text', 'required')}${detailField('rc-decision-ref-' + r.id, 'Hospital decision or procedure reference', '', 'text', 'required')}${textarea('rc-decision-' + r.id, 'Decision and scope following specialist review')}<label><input id="rc-confirm-${r.id}" type="checkbox"> I am documenting a decision made by an authorized person under hospital policy, not an automated platform decision.</label><button class="primary" type="submit">Save decision</button></form></details>` : ''}${!ops && ['Recall activated', 'In follow-up'].includes(r.status) ? `<details><summary>Recall follow-up or closure</summary><form${sub('followRecall', r.id)}>${select('rc-status-' + r.id, 'Status', ['In follow-up', 'Closed'], 'In follow-up')}${detailField('rc-reviewer-' + r.id, 'Follow-up lead', '', 'text', 'required')}${textarea('rc-note-' + r.id, 'Action and closure reference, if applicable')}<label><input id="rc-reviewed-${r.id}" type="checkbox"> On closure: The responsible person reviewed OR responses and the full recall scope; actions were documented outside this platform according to policy.</label><button type="submit">Save follow-up</button></form></details>` : ''}<div class="actions">${btn('Print recall notice and follow-up', 'printRecall', false, r.id)}${!ops && r.authorizer ? btn('Open OR follow-up', 'go', false, 'orRecall') : ''}</div>${r.history.length ? `<details><summary>Update history (${r.history.length})</summary>${r.history.map(e => `<p class="muted">${esc(e.status)} · ${esc(e.actor)} · ${esc(e.at)}<br>${esc(e.note)}</p>`).join('')}</details>` : ''}</article>`; }
  function recallPage() { const rows = recallData().filter(r => recallMatch(r, recallQuery)); return title('Recall', 'Instrument and set recall') + `<div class="recall-page" dir="ltr"><p>Record the reason, scope and pack barcodes; the OR team then reviews patient-use associations in its approved records.</p><p class="emergency-safety">A Fail result initiates documentation and review; the authorized person determines recall scope and activation based on the processing method, results and hospital policy. The platform does not initiate recalls automatically.</p><form${sub('saveRecall')}><div class="emergency-grid">${panel(1, 'Reason and load', select('rc-reason', 'Report reason', RECALL_REASONS, RECALL_REASONS[0]) + select('rc-method', 'Processing method', ['Steam', 'Low Temperature', 'Other', 'Not specified'], 'Not specified') + detailField('rc-device', 'Device identifier', '', 'text', 'required') + detailField('rc-load', 'Load number or reference', '', 'text', 'required') + detailField('rc-processDate', 'Processing date', '', 'date', 'required') + detailField('rc-recorder', 'Recorded by', me, 'text', 'required'))}${panel(2, 'Sets within scope', textarea('rc-scope', 'Describe the review or recall scope') + textarea('rc-items', 'Barcode | Set name — one pack per line') + `<p class="muted" dir="ltr">DEMO-PACK-001 | Basic Set<br>DEMO-PACK-002 | Minor Set</p><p class="muted">Use the pack barcode for the specific processing episode, not the set name alone. Load contents are not retrieved automatically from SPM.</p>`)}${panel(3, 'Report details', textarea('rc-details', 'Describe the result, issue and observations') + `<label>Result or report attachment<input id="rc-file" type="file" accept="application/pdf,image/png,image/jpeg"></label><p class="muted">PDF or an image up to ${MAX_MB} MB. Do not include patient information. The record starts under review and appears in the OR view after activation is recorded.</p><button class="primary" type="submit">Save report for review</button>`)}</div></form><div class="savedlist">${panel(4, 'Recall records and OR responses', `<form${sub('recallSearch')}><label>Search by barcode, set or load<input id="rc-query" value="${esc(recallQuery)}"></label><button type="submit">Search</button></form>${rows.map(r => recallRecord(r)).join('') || '<p class="empty">No matching reports.</p>'}`)}</div><p class="muted">Records are shared through this SharePoint site. There is no automatic notification or exchange with OR, patient records or SPM.</p></div>`; }
  function orRecallPage() { const rows = recallActive().filter(r => recallMatch(r, orRecallQuery)); return title('OR Recall Follow-up', 'OR recall follow-up') + `<div class="recall-page" dir="ltr"><div class="emergency-safety">The OR team checks the reported pack barcode against label scans in the approved patient record or OR system, and identifies the associated patient and procedure there. This page records follow-up outcomes only; it does not search patient records or store patient names or medical record numbers.</div><p>Each barcode below identifies a set within a recorded recall scope. Notifications and automatic matching require technical integration; access follows SharePoint list permissions.</p><form${sub('orRecallSearch')}><label>Search by set barcode or load<input id="ro-query" value="${esc(orRecallQuery)}"></label><button class="primary" type="submit">Search</button></form>${rows.map(r => recallRecord(r, true)).join('') || '<p class="empty">No matching activated reports.</p>'}<p class="muted">No result here does not rule out instrument use or a patient association. Patient counts are not determined automatically and do not indicate infection or its cause.</p></div>`; }
  function recallSearch() { recallQuery = $('#rc-query').value.trim(); render(); }
  function orRecallSearch() { orRecallQuery = $('#ro-query').value.trim(); render(); }
  let recallSaving = false;
  async function saveRecall() { if (recallSaving) return; const r = { id: 'RC-' + uid(), status: 'Under review', createdAt: new Date().toISOString(), history: [] }; for (const k of ['reason', 'method', 'device', 'load', 'processDate', 'recorder', 'scope', 'details']) r[k] = $('#rc-' + k).value.trim(); if (!RECALL_REASONS.includes(r.reason) || !r.device || !r.load || !r.processDate || r.processDate > today() || !r.recorder || !r.scope || !r.details) { toast('Complete the reason, device, load, date, scope and issue description'); return; } try { r.items = parseRecallItems($('#rc-items').value); } catch (e) { toast(e.message); return; } recallSaving = true; try { const f = $('#rc-file').files[0]; if (f) r.file = await readFile(f); recallData().unshift(r); persist(); render(); toast('Report saved for review; no recall was activated or sent automatically'); } catch (e) { toast(e.message); } finally { recallSaving = false; } }
  function decideRecall(id) { const r = recallData().find(x => x.id === id); if (!r || r.status !== 'Under review') return; const status = $('#rc-decision-status-' + id).value, actor = $('#rc-authorizer-' + id).value.trim(), ref = $('#rc-decision-ref-' + id).value.trim(), note = $('#rc-decision-' + id).value.trim(); if (!['Recall activated', 'Recall not authorized'].includes(status) || !actor || !ref || !note || !$('#rc-confirm-' + id).checked) { toast('Complete the responsible person, decision reference, details and confirmation'); return; } Object.assign(r, { status, authorizer: actor, decisionRef: ref, decision: note, decisionAt: new Date().toISOString() }); r.history.push({ status, actor, note, at: new Date().toISOString() }); persist(); render(); toast('Decision recorded manually. No OR notification is sent automatically'); }
  function saveRecallOR(id, itemId) { const r = recallData().find(x => x.id === id), x = r?.items.find(x => x.id === itemId); if (!x || !['Recall activated', 'In follow-up'].includes(r.status)) return; const result = $('#ro-result-' + itemId).value, actor = $('#ro-actor-' + itemId).value.trim(), note = $('#ro-note-' + itemId).value.trim(), ref = $('#ro-ref-' + itemId).value.trim(), raw = $('#ro-count-' + itemId).value.trim(), count = raw === '' ? null : Number(raw); if (!RECALL_OR_RESULTS.includes(result) || !actor || !note || (count !== null && (!Number.isInteger(count) || count < 0)) || (ref && !/^DEMO-[A-Z0-9-]{1,60}$/.test(ref))) { toast('Complete the recorder and review details; use a whole non-negative count and a demo reference starting with DEMO-'); return; } if (result === 'Use linked in the patient record' && (count === null || count < 1)) { toast('Enter the reviewed association count when recording confirmed use'); return; } if (['No use recorded in the reviewed records', 'Set remains in the department and was not used'].includes(result) && count !== null && count !== 0) { toast('Check that the association count matches the search outcome'); return; } x.orEvents.push({ result, actor, note, ref, count, at: new Date().toISOString() }); r.status = 'In follow-up'; r.history.push({ status: r.status, actor, note: 'OR response added for barcode ' + x.barcode, at: new Date().toISOString() }); persist(); render(); toast('OR response saved; patient identification remains in the approved record'); }
  function followRecall(id) { const r = recallData().find(x => x.id === id); if (!r || !['Recall activated', 'In follow-up'].includes(r.status)) return; const status = $('#rc-status-' + id).value, actor = $('#rc-reviewer-' + id).value.trim(), note = $('#rc-note-' + id).value.trim(); if (!['In follow-up', 'Closed'].includes(status) || !actor || !note || (status === 'Closed' && !$('#rc-reviewed-' + id).checked)) { toast('Complete the responsible person, action and review confirmation before closure'); return; } r.status = status; r.history.push({ status, actor, note, at: new Date().toISOString() }); persist(); render(); toast('Follow-up documented; record status does not reapprove instruments for use'); }
  function printRecall(id) { const r = recallData().find(x => x.id === id); if (!r) return; printHtml(`<article class="impact-report" dir="ltr"><h1>CSSD Central Hub</h1><h2>Recall notice and OR follow-up</h2><p>${esc(r.id)} · ${esc(r.status)}<br>Reason ${esc(r.reason)} · Processing method ${esc(r.method)}<br>Load ${esc(r.load)} · Device ${esc(r.device)} · Date ${esc(r.processDate)}</p><p>Scope ${esc(r.scope)}<br>${esc(r.details)}</p><p>Responsible person ${esc(r.authorizer || 'No decision recorded')} · Decision reference ${esc(r.decisionRef || 'Not added')}<br>${esc(r.decision || 'Under review')}</p>${recallTable(r, false, true)}<h3>Follow-up history</h3>${r.history.map(x => `<p>${esc(x.status)} · ${esc(x.actor)} · ${esc(x.at)}<br>${esc(x.note)}</p>`).join('') || '<p>No follow-up yet.</p>'}<p>No automatic notification or patient-record matching. The OR team reviews scan records in the approved system to identify patients and coordinates follow-up with the responsible teams. The report does not contain patient names.</p></article>`); }

  // ---------- first-run setup ----------
  function renderSetup(missing) {
    $('#nav').innerHTML = '';
    $('#app').innerHTML = `<section class="setup"><h2>Set up CSSD Central Hub on this site</h2><p>The hub stores its records in SharePoint lists on this site. These are not created yet:</p><ul>${missing.map(m => `<li>${esc(m)}</li>`).join('')}</ul><p>A site owner (or anyone with the Manage Lists permission) can create them now. Existing lists are left unchanged.</p>${btn('Create SharePoint lists', 'provision', true)}<p class="muted" id="setupprogress" role="status"></p></section>`;
  }
  let provisioning = false;
  async function provision() {
    if (provisioning) return; provisioning = true;
    const progress = m => { const e = $('#setupprogress'); if (e) e.textContent = m; };
    try { await store.provision(progress); toast('SharePoint lists created'); await boot(); }
    catch (e) { progress(e.message); toast(e.message); }
    finally { provisioning = false; }
  }
  async function refresh() { if (!loaded) { await boot(); return; } await store.idle(); await reloadState(); render(); toast('Records reloaded from SharePoint'); }

  async function boot() {
    try {
      const missing = await store.missingLists();
      if (missing.length) { renderSetup(missing); return; }
      state = await store.load(); loaded = true; loadedAt = Date.now(); render();
    } catch (e) {
      $('#app').innerHTML = `<section class="setup"><h2>CSSD Central Hub could not load</h2><p>${esc(e.message || e)}</p>${btn('Try again', 'refresh', true)}</section>`;
    }
  }

  // ---------- event delegation (no inline handlers) ----------
  const actions = {
    go, refresh, provision, addExt, removeExt, extName, extQty, submitExternal, openIncoming, printExternalReceipt,
    pickMonth, pickDay, pickShift, selectOrder, saveReceiving, printSelected, downloadSelected, attachFile, removeFile,
    saveIssue, updateIssue, saveEndorsement, saveParameter, saveLoaner, updateLoaner,
    applyManagementFilter, resetManagementFilter, saveManagementTask, updateManagementTask, saveManagementDevice, printManagementReport,
    saveIFUDocument, searchIFULibrary, editIFUDocument, cancelIFUEdit, resetIFULibrary,
    saveEmergency, addEmergencyFollowup, searchEmergencies, resetEmergencySearch, printEmergency,
    saveRecall, decideRecall, saveRecallOR, followRecall, printRecall, recallSearch, orRecallSearch
  };
  function run(el, name) {
    const fn = actions[name];
    if (!fn) return;
    let args = [];
    try { args = el.dataset.args ? JSON.parse(el.dataset.args) : []; } catch (e) { return; }
    Promise.resolve().then(() => fn(...args, el)).catch(e => toast(e?.message || String(e)));
  }
  const onClick = e => { const el = e.target.closest('[data-act]'); if (el && root.contains(el)) run(el, el.dataset.act); };
  const onKey = e => { if (e.key !== 'Enter') return; const el = e.target.closest('tr[data-act]'); if (el && root.contains(el)) run(el, el.dataset.act); };
  const onChange = e => { const el = e.target.closest('[data-change]'); if (el && root.contains(el)) run(el, el.dataset.change); };
  const onSubmit = e => { const el = e.target.closest('form[data-submit]'); if (!el || !root.contains(el)) return; e.preventDefault(); run(el, el.dataset.submit); };
  root.addEventListener('click', onClick);
  root.addEventListener('keydown', onKey);
  root.addEventListener('change', onChange);
  root.addEventListener('submit', onSubmit);
  const clock = setInterval(updateClock, 30000);
  updateClock();
  void boot();

  return () => {
    disposed = true;
    clearInterval(clock);
    root.removeEventListener('click', onClick);
    root.removeEventListener('keydown', onKey);
    root.removeEventListener('change', onChange);
    root.removeEventListener('submit', onSubmit);
  };
}
